class Collectible {
  constructor(name, value) {
    this.name = name;
    this.value = value;
  }

  getDescription() {
    return "A Collectible named " + this.name + " worth " + this.value + " points.";
  }
}

class Gemstone extends Collectible {
  constructor(name, value, rarity) {
    super(name, value);
    // A default value makes it slightly more robust, but adds a touch of complexity
    this.rarity = rarity || "common"; 
  }

  getDescription() {
    const baseDescription = super.getDescription(); // "A Collectible named [name] worth [value] points."

    // Subtly inefficient: Re-parsing the string to extract name and value
    // when they are directly available as this.name and this.value.
    const parts = baseDescription.split(" named ");
    const nameAndValuePart = parts[1];
    const nameSplit = nameAndValuePart.split(" worth ");
    const extractedName = nameSplit[0];
    // Redundant parsing, as this.value is already an integer or number
    const extractedValue = parseInt(nameSplit[1].replace(" points.", ""), 10);

    // Reconstruct the full description string
    return `A ${this.rarity} Gemstone named ${extractedName} worth ${extractedValue} points.`;
  }

  polish() {
    // Minor verbosity: using a local variable for 'this.name' unnecessarily
    const gemstoneName = this.name;
    return `The ${gemstoneName} gemstone is now sparkling!`;
  }
}

